mapper.select:
SELECT * FROM ( SELECT T0.*, ROWNUM RNUM FROM (
SELECT A.UNITY_LINK_ID, A.UNITY_LINK_SE_CODE, A.UNITY_LINK_NM, A.UNITY_LINK_URL, A.UNITY_LINK_DC, A.FRST_REGISTER_ID, TO_CHAR(A.FRST_REGIST_PNTTM,'YYYY-MM-DD') FRST_REGISTER_PNTTM, (SELECT USER_NM FROM COMVNUSERMASTER WHERE ESNTL_ID = A.FRST_REGISTER_ID) FRST_REGISTER_NM FROM COMTNUNITYLINK A WHERE 1=1
AND UNITY_LINK_NM LIKE '%' || #{searchKeyword} || '%'
AND UNITY_LINK_DC LIKE '%' || #{searchKeyword} || '%'
ORDER BY A.FRST_REGIST_PNTTM DESC
) T0 ) Z WHERE RNUM BETWEEN #{firstIndex} + 1 AND #{firstIndex} + #{recordCountPerPage}
